// DEMO ONLY. Not production authentication. Never store passwords.
const demoKey='procleaning-demo-session';
document.querySelectorAll('.password-toggle').forEach(button=>button.addEventListener('click',()=>{const input=button.parentElement.querySelector('input');const show=input.type==='password';input.type=show?'text':'password';button.textContent=show?'Hide':'Show';button.setAttribute('aria-label',show?'Hide password':'Show password');}));
document.querySelector('.auth-form')?.addEventListener('submit',event=>{event.preventDefault();const form=event.currentTarget;const status=form.querySelector('.auth-status');if(form.dataset.auth==='forgot-password'){status.textContent='Demo reset flow complete. No email has been sent. Return to sign in to enter the demo.';form.reset();return;}const email=form.elements.email.value.trim();const name=form.elements.name?.value.trim()||email.split('@')[0]||'there';try{sessionStorage.setItem(demoKey,JSON.stringify({name,email,demo:true}));form.reset();location.href='account.html';}catch{status.textContent='Browser storage is unavailable. Enable session storage to try this demo.';}});
if(location.pathname.endsWith('/account.html')){let user=null;try{user=JSON.parse(sessionStorage.getItem(demoKey)||'null');}catch{}if(!user?.demo){location.replace('login.html');}else{document.querySelector('[data-customer-name]').textContent=user.name;document.querySelector('[data-customer-email]').textContent=user.email;}document.querySelector('[data-sign-out]')?.addEventListener('click',()=>{sessionStorage.removeItem(demoKey);location.replace('login.html');});}
